import{at as e,it as t,n,vt as r}from"./chunks/framework.D9OOHiq-.js";var i=JSON.parse(`{"title":"EmakiCooking","description":"","frontmatter":{},"headers":[],"relativePath":"modules/cooking/index.md","filePath":"modules/cooking/index.md","lastUpdated":0}`),a={name:`modules/cooking/index.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="emakicooking" tabindex="-1">EmakiCooking <a class="header-anchor" href="#emakicooking" aria-label="Permalink to “EmakiCooking”">​</a></h1><p>下面依次说明 EmakiCooking 做什么, 有哪些工位, 配置放在哪里, 以及全局配置项怎么填</p><p>EmakiCooking 负责在世界里用方块工位做菜. 工位就是世界里用来做菜的那块方块. 它提供砧板, 炒锅, 研磨机, 蒸锅, 烤炉, 榨汁机和发酵桶七类工位. 它管的是方块交互, 坐标状态, 材料输入, 阶段进度和分支产物, 与装备成长无关</p><h2 id="基本信息" tabindex="-1">基本信息 <a class="header-anchor" href="#基本信息" aria-label="Permalink to “基本信息”">​</a></h2><table tabindex="0"><thead><tr><th>项目</th><th>值</th></tr></thead><tbody><tr><td>模块版本</td><td><code>5.0.0</code></td></tr><tr><td>API Jar</td><td><code>emaki-cooking-api-5.0.0.jar</code></td></tr><tr><td>主类</td><td><code>emaki.jiuwu.craft.cooking.EmakiCookingPlugin</code></td></tr><tr><td>主命令</td><td><code>/ecooking</code></td></tr><tr><td>别名</td><td><code>/ec</code></td></tr><tr><td>硬依赖</td><td>EmakiCoreLib</td></tr><tr><td>软依赖</td><td>PlaceholderAPI, CraftEngine, ItemsAdder, Nexo, Oraxen, PacketEvents, MMOItems, NeigeItems</td></tr><tr><td>最低服务端</td><td>Paper 26.1+ (<code>api-version: 26.1</code>, <code>folia-supported: true</code>)</td></tr><tr><td>主要权限</td><td><code>emakicooking.use</code> (默认 true), <code>emakicooking.reload</code> (op), <code>emakicooking.inspect</code> (op), <code>emakicooking.debug</code> (op), <code>emakicooking.admin</code> (op)</td></tr></tbody></table><h2 id="功能页面" tabindex="-1">功能页面 <a class="header-anchor" href="#功能页面" aria-label="Permalink to “功能页面”">​</a></h2><table tabindex="0"><thead><tr><th>页面</th><th>内容</th></tr></thead><tbody><tr><td><a href="./commands.html">命令与权限</a></td><td>重载工位配置, 检查手里物品与目标方块的来源, 重建工位索引和查看调试信息</td></tr><tr><td><a href="./stations.html">工位系统</a></td><td>七类工位的方块来源, 进度状态, 材料缓存, 燃料, 流体和阶段数据</td></tr><tr><td><a href="./recipes.html">配方系统</a></td><td><code>recipes/&lt;station&gt;/</code> 下按工位划分的配方字段与交互差异</td></tr><tr><td><a href="./nutrition.html">营养系统</a></td><td>营养值累积, 越过阈值时触发和数据保存</td></tr><tr><td><a href="./placeholders.html">占位符</a></td><td>PlaceholderAPI 输出的占位符</td></tr><tr><td><a href="./corelib-actions.html">CoreLib 动作</a></td><td>营养值, 阈值复查和配方奖励动作</td></tr><tr><td><a href="./api.html">API 接入</a></td><td><code>EmakiCookingApi</code> 的版本, 插件名和就绪状态探针</td></tr><tr><td><a href="./events.html">事件 API</a></td><td>烹饪和营养流程的 Bukkit 事件</td></tr></tbody></table><h2 id="七类工位" tabindex="-1">七类工位 <a class="header-anchor" href="#七类工位" aria-label="Permalink to “七类工位”">​</a></h2><table tabindex="0"><thead><tr><th>工位</th><th>典型玩法</th></tr></thead><tbody><tr><td>砧板 <code>chopping_board</code></td><td>把食材切成另一种形态</td></tr><tr><td>炒锅 <code>wok</code></td><td>加入材料后控制火候, 翻炒, 出锅</td></tr><tr><td>研磨机 <code>grinder</code></td><td>把物品磨成粉末或其他材料</td></tr><tr><td>蒸锅 <code>steamer</code></td><td>打开界面加燃料和水分, 按蒸制进度出成品</td></tr><tr><td>烤炉 <code>oven</code></td><td>加燃料提升火力, 火力合适时才推进烘烤, 结果由烘烤阶段决定</td></tr><tr><td>榨汁机 <code>juicer</code></td><td>反复压榨材料生成流体, 再用容器按容量盛取饮品</td></tr><tr><td>发酵桶 <code>fermentation_barrel</code></td><td>投入多种材料后开始发酵, 可以提前收取, 正常完成和过度发酵各有不同结果</td></tr></tbody></table><h2 id="默认配置目录" tabindex="-1">默认配置目录 <a class="header-anchor" href="#默认配置目录" aria-label="Permalink to “默认配置目录”">​</a></h2><div class="language-text" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>plugins/EmakiCooking/</span></span>
<span class="line"><span>├── config.yml</span></span>
<span class="line"><span>├── recipes/</span></span>
<span class="line"><span>│   ├── chopping_board/</span></span>
<span class="line"><span>│   ├── wok/</span></span>
<span class="line"><span>│   ├── grinder/</span></span>
<span class="line"><span>│   ├── steamer/</span></span>
<span class="line"><span>│   ├── oven/</span></span>
<span class="line"><span>│   ├── juicer/</span></span>
<span class="line"><span>│   └── fermentation_barrel/</span></span>
<span class="line"><span>├── gui/</span></span>
<span class="line"><span>│   ├── steamer.yml</span></span>
<span class="line"><span>│   ├── oven.yml</span></span>
<span class="line"><span>│   ├── juicer.yml</span></span>
<span class="line"><span>│   ├── fermentation_barrel.yml</span></span>
<span class="line"><span>│   ├── editor_browser_gui.yml</span></span>
<span class="line"><span>│   └── editor_page_gui.yml</span></span>
<span class="line"><span>├── item_adjustments/</span></span>
<span class="line"><span>├── nutrition/</span></span>
<span class="line"><span>├── data/</span></span>
<span class="line"><span>│   ├── nutrition/</span></span>
<span class="line"><span>│   ├── stations/</span></span>
<span class="line"><span>│   │   └── index/</span></span>
<span class="line"><span>│   ├── stations-legacy-backup/</span></span>
<span class="line"><span>│   └── station-tombstones/</span></span>
<span class="line"><span>└── lang/</span></span></code></pre></div><p>目录说明:</p><table tabindex="0"><thead><tr><th>目录 / 文件</th><th>作用</th></tr></thead><tbody><tr><td><code>recipes/</code></td><td>各工位的配方. 改配方先从对应工位的目录开始</td></tr><tr><td><code>gui/steamer.yml</code></td><td>蒸锅的界面配置</td></tr><tr><td><code>gui/oven.yml</code></td><td>烤炉的界面配置</td></tr><tr><td><code>gui/juicer.yml</code></td><td>榨汁机的界面配置</td></tr><tr><td><code>gui/fermentation_barrel.yml</code></td><td>发酵桶的界面配置</td></tr><tr><td><code>item_adjustments/</code></td><td>对输入或输出物品的额外调整</td></tr><tr><td><code>nutrition/</code></td><td>营养类型定义, 随包提供 <code>grain.yml</code>, <code>protein.yml</code>, <code>vegetable.yml</code>, <code>fruit.yml</code>, <code>sugar.yml</code>. 详见营养系统文档</td></tr><tr><td><code>data/nutrition/</code></td><td>玩家营养值持久化数据, 每个玩家一个 <code>&lt;UUID&gt;.yml</code></td></tr><tr><td><code>data/stations/</code></td><td>普通方块工位的 YAML 回退状态目录. 方块实体工位优先把状态写进方块 PDC</td></tr><tr><td><code>data/stations/index/</code></td><td>每个世界一个 <code>&lt;world&gt;.idx</code>, 记录工位坐标, 类型, 物品来源和存储后端, 供区块加载时恢复工位</td></tr><tr><td><code>data/stations-legacy-backup/</code></td><td>旧 YAML 状态成功迁移到方块实体 PDC 后, 原文件备份到这里</td></tr><tr><td><code>data/station-tombstones/</code></td><td>工位被移除时写入墓碑标记的目录, 用来阻止已删除的工位被重新索引, 或在状态残留时复活</td></tr><tr><td><code>config.yml</code></td><td>工位识别, 交互, 限制, 展示实体, 燃料和流体容量等全局配置</td></tr></tbody></table><h2 id="全局配置项" tabindex="-1">全局配置项 <a class="header-anchor" href="#全局配置项" aria-label="Permalink to “全局配置项”">​</a></h2><p>以下是 <code>config.yml</code> 的顶层字段; 工位段与营养段分别在 <a href="./stations.html">工位系统</a> 与 <a href="./nutrition.html">营养系统</a> 中给出</p><table tabindex="0"><thead><tr><th>字段</th><th>类型</th><th>必填</th><th>默认值</th><th>取值范围</th><th>说明</th></tr></thead><tbody><tr><td><code>version</code></td><td>string</td><td>否</td><td><code>&quot;5.0.0&quot;</code></td><td>—</td><td>配置版本号, 升级迁移时用来比对</td></tr><tr><td><code>language</code></td><td>string</td><td>否</td><td><code>&quot;zh_CN&quot;</code></td><td><code>lang/</code> 下存在的语言文件名</td><td>语言文件, 对应 <code>lang/&lt;language&gt;.yml</code></td></tr><tr><td><code>release_default_data</code></td><td>boolean</td><td>否</td><td><code>true</code></td><td>true / false</td><td>是否释放内置的示例数据 (<code>recipes/</code>, <code>item_adjustments/</code>, <code>nutrition/</code>). <code>config.yml</code> 与 <code>lang/</code> 属于版本化文件, <code>gui/</code> 属于静态文件, 不受这一项控制</td></tr><tr><td><code>input_rules.only_recipe_items</code></td><td>boolean</td><td>否</td><td><code>true</code></td><td>true / false</td><td>全局严格模式. 工位段没单独写 <code>only_recipe_items</code> 时用这里的值</td></tr><tr><td><code>station.disabled_worlds</code></td><td>list&lt;string&gt;</td><td>否</td><td><code>[]</code> (不禁用任何世界)</td><td>世界名, 大小写不敏感</td><td>全局禁用工位交互的世界列表. 命中后插件不接管方块交互, 保留原版行为. 随包提供的 <code>config.yml</code> 里只留了注释, 没有写出这个键</td></tr></tbody></table><div class="language-yaml" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#62687b;--shiki-dark:#818e99;"># 只允许可匹配当前工位配方的物品进入输入</span></span>
<span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">input_rules</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">  only_recipe_items</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#62687b;--shiki-dark:#818e99;"># 资源世界与副本世界保留原版交互</span></span>
<span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">station</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">  disabled_worlds</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">world_resource</span></span></code></pre></div><h2 id="世界状态流程" tabindex="-1">世界状态流程 <a class="header-anchor" href="#世界状态流程" aria-label="Permalink to “世界状态流程”">​</a></h2><ol><li>玩家和工位方块交互</li><li>Cooking 判断这个方块是不是配置里的工位</li><li>读取这个坐标上的工位状态</li><li>根据玩家手里的物品, 权限, 容器, 燃料和配方执行操作</li><li>更新工位状态, 例如加入材料, 切割次数, 火候, 燃烧时间, 蒸汽, 水分, 流体容量或发酵进度</li><li>条件满足后发放产物, 盛取流体, 进入下一阶段或执行动作</li><li>如果工位方块是方块实体, 状态写进方块 PDC 并记录索引; 普通方块则回退写入 <code>data/stations/</code> 的 YAML</li><li>重启或区块加载时, Cooking 根据 <code>data/stations/index/&lt;world&gt;.idx</code> 定位并恢复工位状态</li></ol><h2 id="与外部方块插件的关系" tabindex="-1">与外部方块插件的关系 <a class="header-anchor" href="#与外部方块插件的关系" aria-label="Permalink to “与外部方块插件的关系”">​</a></h2><p>有 CraftEngine, ItemsAdder, Nexo 这些软依赖时, Cooking 能识别它们提供的自定义方块或物品. 没装这些插件时, 对应的自定义工位不会生效, 但原版物品和方块相关功能仍可按配置运行</p><p>展示实体可通过 <code>display_entities.backend</code> 配置:</p><ul><li><code>auto</code>: 装了 PacketEvents 就用虚拟展示实体, 不可用时回退到 Bukkit 的真实 ItemDisplay</li><li><code>packet_events</code>: 优先使用 PacketEvents, 加载失败仍然回退到 Bukkit</li><li><code>bukkit</code>: 始终使用 Bukkit 的真实 ItemDisplay</li></ul>`,23)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};